// =============================================================================
// Cosmos DB Provider — Required fixes for EF Core 9 (apply to your Cosmos project)
// =============================================================================

using Microsoft.EntityFrameworkCore;

// BREAKING CHANGE 1: Discriminator property renamed from "Discriminator" to "$type"
// Existing documents use "Discriminator". You must explicitly configure the old name
// to avoid query failures on existing data.
//
// BREAKING CHANGE 2: id property no longer contains the discriminator prefix.
// Existing documents have ids like "Product|123"; EF Core 9 expects just "123".
// Use HasRootDiscriminatorInJsonId(true) to preserve the old format.

class CosmosDbContextFix : DbContext
{
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve old discriminator property name for existing documents
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve old compound id format ("EntityType|KeyValue")
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }

    // Fix 3: Sync I/O is no longer supported on the Cosmos DB provider.
    // All synchronous calls (ToList(), SaveChanges(), First(), etc.) now throw.
    // You MUST convert to async equivalents:

    // BEFORE (BREAKS in EF Core 9):
    //   var items = dbContext.Sessions.Where(s => s.IsActive).ToList();
    //   dbContext.SaveChanges();

    // AFTER:
    //   var items = await dbContext.Sessions.Where(s => s.IsActive).ToListAsync();
    //   await dbContext.SaveChangesAsync();
}

class Session
{
    public string Id { get; set; } = default!;
    public bool IsActive { get; set; }
}

